package com.canteen.management.service.impl;import java.time.LocalDate;import java.util.ArrayList;import java.util.List;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Service;import com.canteen.management.entity.Notification;import com.canteen.management.repository.NotificationRepository;import java.time.LocalDateTime;import java.time.format.DateTimeFormatter;import com.canteen.management.dto.OrderRequest;import com.canteen.management.dto.OrderResponse;import com.canteen.management.entity.Food;import com.canteen.management.entity.Order;import com.canteen.management.repository.FoodRepository;import com.canteen.management.repository.OrderRepository;import com.canteen.management.service.OrderService;@Servicepublic class OrderServiceImpl implements OrderService {    @Autowired    private OrderRepository orderRepository;    @Autowired    private FoodRepository foodRepository;    @Autowired    private NotificationRepository notificationRepository;    @Override    public OrderResponse placeOrder(OrderRequest orderRequest) {        Food food = foodRepository.findById(orderRequest.getFoodId())                .orElseThrow(() -> new RuntimeException("Food Not Found"));        if (food.getQuantity() < orderRequest.getQuantity()) {            throw new RuntimeException("Insufficient Quantity Available");        }        Double totalPrice = food.getPrice() * orderRequest.getQuantity();        food.setQuantity(food.getQuantity() - orderRequest.getQuantity());        foodRepository.save(food);        Order order = new Order();        order.setOrderNumber("ORD" + System.currentTimeMillis());        order.setQrCode("QR" + System.currentTimeMillis());        order.setStudentId(orderRequest.getStudentId());        order.setFoodId(orderRequest.getFoodId());        order.setQuantity(orderRequest.getQuantity());        order.setTotalPrice(totalPrice);        order.setOrderDate(LocalDate.now().toString());        order.setOrderStatus("PLACED");        order.setPaymentStatus("Pending");        order.setCanteenId(food.getCanteenId());        Order savedOrder = orderRepository.save(order);        Notification notification = new Notification();        notification.setStudentId(savedOrder.getStudentId());        notification.setTitle("🛒 Order Placed");        notification.setMessage(                "Your order " + savedOrder.getOrderNumber() + " has been placed successfully."        );        notification.setTime(                LocalDateTime.now().format(                        DateTimeFormatter.ofPattern("dd MMM yyyy hh:mm a")                )        );        notification.setRead(false);        notificationRepository.save(notification);        return new OrderResponse(                savedOrder.getId(),                savedOrder.getOrderNumber(),                savedOrder.getStudentId(),                savedOrder.getFoodId(),                savedOrder.getQuantity(),                savedOrder.getTotalPrice(),                savedOrder.getOrderDate(),                savedOrder.getOrderStatus(),                savedOrder.getQrCode(),                savedOrder.getPaymentStatus(),                savedOrder.getCanteenId(),                "Order Placed Successfully"        );    }    @Override    public List<OrderResponse> getAllOrders() {        List<Order> orders = orderRepository.findAll();        List<OrderResponse> responseList = new ArrayList<>();        for (Order order : orders) {            responseList.add(                    new OrderResponse(                            order.getId(),                            order.getOrderNumber(),                            order.getStudentId(),                            order.getFoodId(),                            order.getQuantity(),                            order.getTotalPrice(),                            order.getOrderDate(),                            order.getOrderStatus(),                            order.getQrCode(),                            order.getPaymentStatus(),                            order.getCanteenId(),                            "Success"                    )            );        }        return responseList;    }    @Override    public List<OrderResponse> getOrdersByStudentId(String studentId) {        List<Order> orders = orderRepository.findByStudentId(studentId);        List<OrderResponse> responseList = new ArrayList<>();        for (Order order : orders) {            responseList.add(new OrderResponse(                order.getId(),                order.getOrderNumber(),                order.getStudentId(),                order.getFoodId(),                order.getQuantity(),                order.getTotalPrice(),                order.getOrderDate(),                    order.getOrderStatus(),                    order.getQrCode(),                    order.getPaymentStatus(),                order.getCanteenId(),                "Success"            ));        }        return responseList;    }    @Override    public OrderResponse updateOrderStatus(Long id, String status) {        Order order = orderRepository.findById(id)                .orElseThrow(() -> new RuntimeException("Order Not Found"));        order.setOrderStatus(status);        if ("Completed".equalsIgnoreCase(status)) {            order.setPaymentStatus("Paid");            order.setQrCode(null);        }        Order savedOrder = orderRepository.save(order);        Notification notification = new Notification();        notification.setStudentId(savedOrder.getStudentId());        if (status.equalsIgnoreCase("PREPARING")) {            notification.setTitle("🍳 Order Preparing");            notification.setMessage(                    "Your order " + savedOrder.getOrderNumber() + " is being prepared."            );        } else if (status.equalsIgnoreCase("COMPLETED")) {            notification.setTitle("✅ Order Ready");            notification.setMessage(                    "Your order " + savedOrder.getOrderNumber() + " is ready for pickup."            );        } else if (status.equalsIgnoreCase("COLLECTED")) {            notification.setTitle("🎉 Order Collected");            notification.setMessage(                    "Thank you! Your order "                            + savedOrder.getOrderNumber()                            + " has been collected."            );        } else {            notification.setTitle("📦 Order Updated");            notification.setMessage(                    "Your order status changed to " + status            );        }        notification.setTime(                LocalDateTime.now().format(                        DateTimeFormatter.ofPattern("dd MMM yyyy hh:mm a")                )        );        notification.setRead(false);        notificationRepository.save(notification);        return new OrderResponse(                savedOrder.getId(),                savedOrder.getOrderNumber(),                savedOrder.getStudentId(),                savedOrder.getFoodId(),                savedOrder.getQuantity(),                savedOrder.getTotalPrice(),                savedOrder.getOrderDate(),                savedOrder.getOrderStatus(),                savedOrder.getQrCode(),                savedOrder.getPaymentStatus(),                savedOrder.getCanteenId(),                "Order Status Updated"        );    }}